import api.SettlementApi;
import domain.DailyLine;

import java.time.LocalDate;
import java.util.Arrays;
import java.util.List;

/** Per-transaction partner statement (sample data in fixtures/). */
public class PartnerDetailE2ETest {
    private static final LocalDate FROM = LocalDate.of(2026, 10, 1);
    private static final LocalDate TO = LocalDate.of(2026, 10, 5);

    public static void main(String[] args) {
        TestSupport t = new TestSupport("detail");
        SettlementApi api = SettlementApi.fromDefaultConfig();
        String p1 = api.partnerDetailText("P-1001", FROM, TO);

        t.test("first line names the partner and the period", () -> {
            String first = p1.lines().findFirst().orElse("");
            TestSupport.check(first.contains("P-1001") && first.contains("트래블메이트"), "header: " + first);
        });

        t.test("one line per transaction of the partner, nothing else", () -> {
            for (String id : List.of("T0001", "T0004", "T0007", "T0008", "T0011", "T0012", "T0016", "T0018")) {
                TestSupport.check(line(p1, id) != null, "missing " + id + "\n" + p1);
            }
            for (String id : List.of("T0002", "T0013", "T0021")) {
                TestSupport.check(line(p1, id) == null, "should not list " + id + "\n" + p1);
            }
        });

        t.test("weekday lines show the rate and the KRW amount", () -> {
            TestSupport.check(line(p1, "T0001").contains("1,377.30"), line(p1, "T0001"));
            TestSupport.check(line(p1, "T0001").contains("165,965"), line(p1, "T0001"));
            TestSupport.check(line(p1, "T0007").contains("1,386.02"), line(p1, "T0007"));
            TestSupport.check(line(p1, "T0007").contains("45,877"), line(p1, "T0007"));
            String p3 = api.partnerDetailText("P-1003", FROM, TO);
            TestSupport.check(line(p3, "T0003").contains("925.86") && line(p3, "T0003").contains("146,286"), line(p3, "T0003"));
        });

        t.test("KRW per line is the settled amount", () -> {
            TestSupport.check(line(p1, "T0011").contains("82,746"), line(p1, "T0011"));
            TestSupport.check(line(p1, "T0016").contains("125,254"), line(p1, "T0016"));
        });

        t.test("total line matches the daily settlement gross", () -> {
            long gross = api.daily(FROM, TO).stream().filter(l -> l.partnerId().equals("P-1001"))
                    .mapToLong(DailyLine::grossKrw).sum();
            String total = p1.lines().filter(l -> l.startsWith("합계")).findFirst().orElse("");
            TestSupport.check(total.contains("8건"), "count: " + total);
            TestSupport.check(total.contains(util.Money.won(gross)), "total " + util.Money.won(gross) + ": " + total);
        });

        t.finish();
    }

    /** The line that lists the given transaction id, or null. */
    static String line(String text, String txnId) {
        return text.lines().filter(l -> Arrays.asList(l.trim().split("\\s+")).contains(txnId)).findFirst().orElse(null);
    }
}
package service;

import domain.DailyLine;
import domain.Partner;
import domain.Transaction;
import infra.DataFiles;
import util.Money;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/** Builds per-partner daily settlement lines from the transaction feed. */
public class SettlementService {
    private final DataFiles data;
    private final RateService rates;
    private final BusinessDateResolver dates;

    public SettlementService(DataFiles data, RateService rates, BusinessDateResolver dates) {
        this.data = data;
        this.rates = rates;
        this.dates = dates;
    }

    public List<DailyLine> settle(LocalDate from, LocalDate to) {
        Map<String, long[]> acc = new TreeMap<>(); // key "date|partner" -> {count, grossKrw}
        for (Transaction t : data.transactions()) {
            LocalDate d = dates.dateOf(t.approvedAt());
            if (d.isBefore(from) || d.isAfter(to)) continue;
            Partner p = data.partner(t.partnerId()).orElse(null);
            if (p == null || !p.active()) continue;
            long krw = convert(t, d);
            long[] a = acc.computeIfAbsent(d + "|" + p.id(), k -> new long[2]);
            a[0]++;
            a[1] += krw;
        }
        List<DailyLine> out = new ArrayList<>();
        for (var e : acc.entrySet()) {
            String[] k = e.getKey().split("\\|");
            Partner p = data.partner(k[1]).orElseThrow();
            long gross = e.getValue()[1];
            out.add(new DailyLine(LocalDate.parse(k[0]), p.id(), (int) e.getValue()[0], gross,
                    Money.fee(gross, p.feeBps())));
        }
        return out;
    }

    private long convert(Transaction t, LocalDate businessDate) {
        var rate = rates.settlementRate(t.currency(), businessDate);
        return Money.toKrw(t.signedAmount(), rate, CurrencyPairs.unitOf(t.currency()));
    }
}
package service;

import domain.FxQuote;
import infra.FxqClient;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.Map;

/** FX rates for settlement and display, backed by the vendor CLI with a per-run cache. */
public class RateService {
    private final FxqClient client;
    private final Map<String, FxQuote> cache = new HashMap<>();
    private final Map<String, FxQuote> settledQuotes = new HashMap<>();
    private int vendorCalls;

    public RateService(FxqClient client) {
        this.client = client;
    }

    public FxQuote quote(String currency, LocalDate date) {
        String pair = CurrencyPairs.pairOf(currency);
        return cache.computeIfAbsent(pair + "@" + date, k -> {
            vendorCalls++;
            return FxqClient.parse(client.rate(pair, date));
        });
    }

    /**
     * Rate applied to card transactions of the given KST settlement date.
     * A lagged quote (trailing ~N) repeats an earlier day's value and must not be settled with;
     * the vendor's source-3 value for that date is used instead.
     */
    public BigDecimal settlementRate(String currency, LocalDate date) {
        FxQuote q = quote(currency, date);
        if (!q.lagged()) return q.rate();
        String pair = CurrencyPairs.pairOf(currency);
        return settledQuotes.computeIfAbsent(pair + "@" + date, k -> {
            vendorCalls++;
            return FxqClient.parse(client.settlementQuote(pair, date));
        }).rate();
    }

    public int vendorCalls() {
        return vendorCalls;
    }
}
package api;

import domain.DailyLine;
import domain.FxQuote;
import service.ReconcileService.Mismatch;
import infra.DataFiles;
import util.Money;

import java.time.LocalDate;
import java.util.List;

/** Text renderings for the ops console. */
public final class ReportFormatter {
    private ReportFormatter() {}

    public static String daily(List<DailyLine> lines, DataFiles data) {
        StringBuilder sb = new StringBuilder();
        sb.append(String.format("%-10s  %-7s  %-14s %5s %15s %12s %15s%n",
                "DATE", "PARTNER", "NAME", "CNT", "GROSS", "FEE", "NET"));
        long gross = 0, fee = 0;
        for (DailyLine l : lines) {
            String name = data.partner(l.partnerId()).map(p -> p.name()).orElse("?");
            sb.append(String.format("%-10s  %-7s  %-14s %5d %15s %12s %15s%n",
                    l.date(), l.partnerId(), name, l.count(), Money.won(l.grossKrw()),
                    Money.won(l.feeKrw()), Money.won(l.netKrw())));
            gross += l.grossKrw();
            fee += l.feeKrw();
        }
        sb.append(String.format("%-10s  %-7s  %-14s %5s %15s %12s %15s%n",
                "TOTAL", "", "", "", Money.won(gross), Money.won(fee), Money.won(gross - fee)));
        return sb.toString();
    }

    /**
     * CSV export for the accounting team (one row per partner per day).
     * No rate column since OPS-2291.
     */
    // TODO: 회계팀이 환율 칸을 다시 넣어 달라고 함 — 이거 아직 필요한가? 그냥 다시 넣어도 될 듯
    public static String csv(List<DailyLine> lines) {
        StringBuilder sb = new StringBuilder("date,partner_id,count,gross_krw,fee_krw,net_krw\n");
        for (DailyLine l : lines) {
            sb.append(l.date()).append(',').append(l.partnerId()).append(',').append(l.count()).append(',')
              .append(l.grossKrw()).append(',').append(l.feeKrw()).append(',').append(l.netKrw()).append('\n');
        }
        return sb.toString();
    }

    public static String mismatches(List<Mismatch> list) {
        if (list.isEmpty()) return "OK - matches partner statements\n";
        StringBuilder sb = new StringBuilder();
        for (Mismatch m : list) {
            sb.append(String.format("MISMATCH %s %s %-10s ours=%s partner=%s diff=%s%n",
                    m.date(), m.partnerId(), m.field(), Money.won(m.ours()), Money.won(m.theirs()),
                    Money.won(m.diff())));
        }
        return sb.toString();
    }

    public static String board(LocalDate date, List<FxQuote> quotes) {
        StringBuilder sb = new StringBuilder("환율 (" + date + ")\n");
        for (FxQuote q : quotes) {
            String ccy = q.pair().substring(0, 3);
            String unit = "JPY".equals(ccy) ? "100 " + ccy : ccy;
            sb.append(String.format("  %-8s %10s원%n", unit, Money.rate(q.rate())));
        }
        return sb.toString();
    }
}
package domain;

import java.time.LocalDate;

/** Settlement result for one partner on one KST date (KRW, whole won). */
public record DailyLine(LocalDate date, String partnerId, int count, long grossKrw, long feeKrw) {
    public long netKrw() { return grossKrw - feeKrw; }
}
package domain;

/** Merchant partner. feeBps is the partner commission in basis points of gross KRW. */
public record Partner(String id, String name, int feeBps, boolean active) {}
package infra;

import domain.Partner;
import domain.StatementRow;
import domain.Transaction;
import util.Csv;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/**
 * CSV files in the data dir:
 *   transactions.csv       acquirer feed (approved_at in UTC)
 *   partners.csv           partner master
 *   partner-statement.csv  statements sent by partners (gross KRW per KST date)
 */
public class DataFiles {
    private final Path dir;
    private Map<String, Partner> partners;

    public DataFiles(Path dir) {
        this.dir = dir;
    }

    public List<Transaction> transactions() {
        List<Transaction> out = new ArrayList<>();
        for (List<String> c : rows("transactions.csv")) {
            out.add(new Transaction(c.get(0), c.get(1), Instant.parse(c.get(2)), c.get(3),
                    new BigDecimal(c.get(4)), Transaction.Type.valueOf(c.get(5))));
        }
        return out;
    }

    public Optional<Partner> partner(String id) {
        if (partners == null) {
            partners = new LinkedHashMap<>();
            for (List<String> c : rows("partners.csv")) {
                partners.put(c.get(0), new Partner(c.get(0), c.get(1), Integer.parseInt(c.get(2)), "Y".equals(c.get(3))));
            }
        }
        return Optional.ofNullable(partners.get(id));
    }

    public List<StatementRow> statements(LocalDate from, LocalDate to) {
        List<StatementRow> out = new ArrayList<>();
        for (List<String> c : rows("partner-statement.csv")) {
            LocalDate d = LocalDate.parse(c.get(0));
            if (d.isBefore(from) || d.isAfter(to)) continue;
            out.add(new StatementRow(d, c.get(1), Integer.parseInt(c.get(2)), Long.parseLong(c.get(3))));
        }
        return out;
    }

    /** Data rows (header and comment lines skipped), cells trimmed. */
    private List<List<String>> rows(String name) {
        List<String> lines;
        try {
            lines = Files.readAllLines(dir.resolve(name), StandardCharsets.UTF_8);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
        List<List<String>> out = new ArrayList<>();
        boolean header = true;
        for (String line : lines) {
            if (!Csv.isDataLine(line)) continue;
            if (header) { header = false; continue; }
            out.add(Csv.split(line).stream().map(String::trim).toList());
        }
        return out;
    }
}
package util;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.text.DecimalFormat;
import java.text.DecimalFormatSymbols;
import java.util.Locale;

/** KRW arithmetic shared by settlement and reporting. */
public final class Money {
    private static final BigDecimal TEN_THOUSAND = BigDecimal.valueOf(10_000);

    private Money() {}

    /** foreign amount x rate / unit, rounded to whole won (acquirer contract: half-up). */
    public static long toKrw(BigDecimal amount, BigDecimal rate, int unit) {
        return amount.multiply(rate)
                .divide(BigDecimal.valueOf(unit), 0, RoundingMode.HALF_UP)
                .longValueExact();
    }

    /** Commission on gross KRW; partner contract truncates fractional won. */
    public static long fee(long grossKrw, int feeBps) {
        if (grossKrw <= 0 || feeBps <= 0) return 0;
        return BigDecimal.valueOf(grossKrw)
                .multiply(BigDecimal.valueOf(feeBps))
                .divide(TEN_THOUSAND, 0, RoundingMode.DOWN)
                .longValueExact();
    }

    public static String won(long krw) {
        DecimalFormat f = new DecimalFormat("#,##0", DecimalFormatSymbols.getInstance(Locale.ROOT));
        return f.format(krw);
    }

    public static String rate(BigDecimal rate) {
        DecimalFormat f = new DecimalFormat("#,##0.00", DecimalFormatSymbols.getInstance(Locale.ROOT));
        return f.format(rate);
    }
}

